if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_hostname() {
    local config_file="$HOME/.ssh/config"
    local known_hosts="$HOME/.ssh/known_hosts"
    if [[ -r "$config_file" ]]; then
        gawk 'tolower($1) == "host" {
            for (i = 2; i <= NF; i++) {
                if ($i ~ /^#/) break
                if ($i ~ /[*?!]/) continue
                print $i
            }
        }' "$config_file"
    fi
    if [[ -r "$known_hosts" ]]; then
        gawk '{
            count = split($1, hosts, ",")
            for (i = 1; i <= count; i++) {
                host = hosts[i]
                if (host == "" || substr(host, 1, 1) == "|") continue
                if (substr(host, 1, 1) == "[") {
                    host = substr(host, 2)
                    pos = index(host, "]")
                    if (pos > 0) host = substr(host, 1, pos - 1)
                }
                print host
            }
        }' "$known_hosts"
    fi
}

_choice_ssh_cipher() {
    command ssh -Q cipher
}

_choice_ssh_hostkeyalgorithms() {
    command ssh -Q hostkeyalgorithms
}

